package com.nextaicommerce.platform.config;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import java.net.URI;
import java.net.http.*;
import java.util.*;
import org.junit.jupiter.api.Test;

class LocalIntegrationSafetyTest {
    HttpRequest get(String url){return HttpRequest.newBuilder(URI.create(url)).GET().build();}
    HttpRequest post(String url,String body){return HttpRequest.newBuilder(URI.create(url)).POST(HttpRequest.BodyPublishers.ofString(body)).build();}
    @Test void localReadsRequireExplicitScopeAndDoNotLeak(){var p=new LocalIntegrationSafety(true);var r=get("https://sellingpartnerapi-na.amazon.com/sellers/v1/marketplaceParticipations");assertThrows(IllegalStateException.class,()->p.checkRequest(r));try(var scope=p.manualRequest()){assertDoesNotThrow(()->p.checkRequest(r));}assertThrows(IllegalStateException.class,()->p.checkRequest(r));}
    @Test void allBusinessMutationsAreDeniedEvenInsideUserScope(){var p=new LocalIntegrationSafety(true);try(var s=p.manualRequest()){for(String url:List.of("https://sellingpartnerapi-na.amazon.com/inbound/fba/2024-03-20/inboundPlans","https://sellingpartnerapi-na.amazon.com/mfn/v0/shipments","https://apis.fedex.com/ship/v1/shipments","https://apis-sandbox.fedex.com/ship/v1/shipments","https://example.myshopify.com/admin/api/2026-10/orders.json"))assertThrows(IllegalStateException.class,()->p.checkRequest(post(url,"{}")),url);}}
    @Test void readOnlyPostsAndOauthRemainUsable(){var p=new LocalIntegrationSafety(true);try(var s=p.manualRequest()){for(String url:List.of("https://api.amazon.com/auth/o2/token","https://sellingpartnerapi-na.amazon.com/reports/2021-06-30/reports","https://sellingpartnerapi-na.amazon.com/products/fees/v0/feesEstimate","https://apis.fedex.com/rate/v1/rates/quotes","https://example.myshopify.com/admin/oauth/access_token"))assertDoesNotThrow(()->p.checkRequest(post(url,"{}")),url);}}
    @Test void graphqlAllowsReadButRejectsMutationsAndUnknownBodies(){var p=new LocalIntegrationSafety(true);String url="https://example.myshopify.com/admin/api/2026-10/graphql.json";try(var s=p.manualRequest()){assertDoesNotThrow(()->p.checkRequest(post(url,"{\"query\":\"query Orders { orders { id } }\"}")));for(String body:List.of("{\"query\":\"mutation { inventorySetQuantities { id } }\"}","{}","not json"))assertThrows(IllegalStateException.class,()->p.checkRequest(post(url,body)));}}
    @Test void restoredRunsAreNotEligibleAndRegistryIsProcessLocal(){var p=new LocalIntegrationSafety(true);UUID restored=UUID.randomUUID();assertFalse(p.allowedRun(restored));assertThrows(IllegalStateException.class,()->p.allowRun(restored));try(var scope=p.manualRequest()){p.allowRun(restored);}assertTrue(p.allowedRun(restored));assertFalse(new LocalIntegrationSafety(true).allowedRun(restored));}
    @Test void deniedRequestNeverReachesTransport()throws Exception{var delegate=mock(HttpClient.class);var p=new LocalIntegrationSafety(true);var guarded=p.guard(delegate);try(var s=p.manualRequest()){assertThrows(IllegalStateException.class,()->guarded.send(post("https://apis.fedex.com/ship/v1/shipments","{}"),HttpResponse.BodyHandlers.ofString()));}verifyNoInteractions(delegate);}
    @Test void nonLocalTransportAndPolicyAreUnchanged(){var delegate=mock(HttpClient.class);var p=new LocalIntegrationSafety(false);assertSame(delegate,p.guard(delegate));assertDoesNotThrow(()->p.checkRequest(post("https://apis.fedex.com/ship/v1/shipments","{}")));}
    @Test void localSchedulerDoesNotRegisterCollectorsOrRestoredQueueWorkers(){assertTrue(LocalManualSyncConfiguration.permitted(com.nextaicommerce.platform.sync.AmazonSyncWorker.class,"processNext"));assertFalse(LocalManualSyncConfiguration.permitted(com.nextaicommerce.platform.sync.AmazonRecurringSyncScheduler.class,"enqueueDueWork"));assertFalse(LocalManualSyncConfiguration.permitted(com.nextaicommerce.platform.shopify.ShopifyOrderPolling.class,"tick"));assertFalse(LocalManualSyncConfiguration.permitted(com.nextaicommerce.platform.shipping.OrderRecipientWorker.class,"fetch"));}
    @Test void asyncManualContextIsCopiedAndThenCleared()throws Exception{var p=new LocalIntegrationSafety(true);var executor=new LocalManualSyncConfiguration().localManualExecutor(p);executor.initialize();try{var allowed=new java.util.concurrent.CompletableFuture<Boolean>();try(var scope=p.manualRequest()){executor.execute(()->allowed.complete(p.manualReadActive()));}assertTrue(allowed.get(2,java.util.concurrent.TimeUnit.SECONDS));var absent=new java.util.concurrent.CompletableFuture<Boolean>();executor.execute(()->absent.complete(p.manualReadActive()));assertFalse(absent.get(2,java.util.concurrent.TimeUnit.SECONDS));}finally{executor.shutdown();}}

    @Test void pageOpenAndProgressPollingDoNotAuthorizeRemoteReads(){for(String path:List.of("/app/orders","/app/marketplace-skus","/app/inventory/replenishment","/app/orders/sync/status","/app/marketplace-skus/fba-inventory"))assertFalse(LocalManualSyncConfiguration.explicitReadAction("GET",path));assertTrue(LocalManualSyncConfiguration.explicitReadAction("POST","/app/orders/sync"));assertFalse(LocalManualSyncConfiguration.explicitReadAction("POST","/app/orders/123/buy-shipping/purchase"));}

}
